ingress "$G6" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "192.168.30.0/24", "Description": "FWShift: default"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "198.51.100.0/24", "Description": "FWShift: ipv4rule 6"}]}, {"IpProtocol": "47", "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: ipv4rule 9"}]}]
FWSHIFT_JSON
egress "$G6" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "192.168.30.0/24", "Description": "FWShift: default"}]}, {"IpProtocol": "icmp", "FromPort": 3, "ToPort": 4, "IpRanges": [{"CidrIp": "198.51.100.0/24", "Description": "FWShift: ipv4rule 15"}]}]
FWSHIFT_JSON
ingress "$G7" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "198.51.100.0/24", "Description": "FWShift: default"}]}, {"IpProtocol": "icmp", "FromPort": 3, "ToPort": 4, "IpRanges": [{"CidrIp": "192.168.30.0/24", "Description": "FWShift: ipv4rule 15"}]}, {"IpProtocol": "icmp", "FromPort": 8, "ToPort": 0, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: ipv4rule 5"}]}]
FWSHIFT_JSON
egress "$G7" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "198.51.100.0/24", "Description": "FWShift: default"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "192.168.30.10/32", "Description": "FWShift: ipv4rule 6"}]}]
FWSHIFT_JSON
ingress "$G8" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "198.51.100.0/24", "Description": "FWShift: default"}]}, {"IpProtocol": "icmp", "FromPort": 3, "ToPort": 4, "IpRanges": [{"CidrIp": "192.168.30.0/24", "Description": "FWShift: ipv4rule 15"}]}, {"IpProtocol": "icmp", "FromPort": 8, "ToPort": 0, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: ipv4rule 5"}]}]
FWSHIFT_JSON
egress "$G8" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "198.51.100.0/24", "Description": "FWShift: default"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "192.168.30.10/32", "Description": "FWShift: ipv4rule 6"}]}, {"IpProtocol": "tcp", "FromPort": 4840, "ToPort": 4840, "IpRanges": [{"CidrIp": "192.168.10.20/32", "Description": "FWShift: ipv4rule 1"}]}]
FWSHIFT_JSON
ingress "$G9" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "198.51.100.0/24", "Description": "FWShift: default"}]}, {"IpProtocol": "icmp", "FromPort": 3, "ToPort": 4, "IpRanges": [{"CidrIp": "192.168.30.0/24", "Description": "FWShift: ipv4rule 15"}]}, {"IpProtocol": "icmp", "FromPort": 8, "ToPort": 0, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: ipv4rule 5"}]}]
FWSHIFT_JSON
