[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "198.51.100.0/24", "Description": "FWShift: default"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "192.168.30.10/32", "Description": "FWShift: ipv4rule 6"}]}, {"IpProtocol": "tcp", "FromPort": 502, "ToPort": 502, "IpRanges": [{"CidrIp": "192.168.10.30/32", "Description": "FWShift: ipv4rule 3"}]}]
FWSHIFT_JSON
ingress "$G10" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "198.51.100.0/24", "Description": "FWShift: default"}]}, {"IpProtocol": "udp", "FromPort": 514, "ToPort": 514, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: ipv4rule 4"}]}, {"IpProtocol": "icmp", "FromPort": 3, "ToPort": 4, "IpRanges": [{"CidrIp": "192.168.30.0/24", "Description": "FWShift: ipv4rule 15"}]}, {"IpProtocol": "icmp", "FromPort": 8, "ToPort": 0, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: ipv4rule 5"}]}]
